	// S_EAST_ch0_C5_R0 M_WEST_ch2_C5_R0 net6

	XAie_StrmConnCctEnable(&DevInst, XAie_TileLoc(5, 1), EAST, 0, WEST, 2);

	// S_EAST_ch1_C5_R0 M_WEST_ch3_C5_R0 net7

	XAie_StrmConnCctEnable(&DevInst, XAie_TileLoc(5, 1), EAST, 1, WEST, 3);

