	// S_EAST_ch2_C3_R0->M_S2MM_DMA_ch0_C3_R0 nets: net4 
	XAie_StrmPktSwSlaveSlotEnable(&DevInst, XAie_TileLoc(3, 1), EAST, 2, 0, {.PktId=2, .PktType=0}, 0x1f, 1, 0);

