	//configure master M_WEST_ch2_C6_R0 nets: net68 

	XAie_StrmPktSwMstrPortEnable(&DevInst, XAie_TileLoc(6, 1), WEST, 2, XAIE_SS_PKT_DROP_HEADER, 0, 0x1);


